import{_ as a,o as r,c as n,ai as e}from"./chunks/framework.ampVZV4B.js";const c=JSON.parse('{"title":"低成本 MVP 验证","description":"","frontmatter":{},"headers":[],"relativePath":"ai/business/mvp-validation.md","filePath":"ai/business/mvp-validation.md"}'),o={name:"ai/business/mvp-validation.md"};function s(i,t,l,d,p,h){return r(),n("div",null,[...t[0]||(t[0]=[e('<h1 id="低成本-mvp-验证" tabindex="-1">低成本 MVP 验证 <a class="header-anchor" href="#低成本-mvp-验证" aria-label="Permalink to “低成本 MVP 验证”">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>「先做个 MVP 试试」这句话，多数时候是个自欺欺人的开始——因为大多数人的 MVP 是「把产品砍到只剩三个功能」，然后花两个月写完，上线无人问津，得出「项目失败」的结论。其实那两个月里，唯一被验证的事情是：<strong>你能不能把它写出来</strong>（显然能）。至于有没有人要，从头到尾没被检验过。</p><p>真正的 MVP 验证，核心是一句话：<strong>在写代码之前，先验证「有人愿意为此付钱/付出行动」</strong>。这篇讲具体做法：先卖再做的几种替代形态、最小验证指标怎么定、以及最重要的——什么条件下止损。</p><h2 id="拆解" tabindex="-1">拆解 <a class="header-anchor" href="#拆解" aria-label="Permalink to “拆解”">​</a></h2><h3 id="_1-先卖再做-三种可落地的验证形态" tabindex="-1">1. 先卖再做：三种可落地的验证形态 <a class="header-anchor" href="#_1-先卖再做-三种可落地的验证形态" aria-label="Permalink to “1. 先卖再做：三种可落地的验证形态”">​</a></h3><p><strong>形态一：落地页验证</strong></p><p>一晚上能做完的事：一个单页，讲清楚「给谁、解决什么问题、怎么解决」，放一个「加入等候名单」或「立即预约」按钮，然后把目标人群能触达的渠道（朋友圈、社群、垂直论坛）投一遍。看的不是 UV 多少，而是<strong>转化率和留下邮箱/微信的人是不是目标人群</strong>。页面可以手写，流量可以很少，但信息必须是最终产品的真实描述——别为了好看夸大，那会污染验证结果。</p><p><strong>形态二：预售验证</strong></p><p>比落地页硬得多的信号：<strong>先把收费链接挂出去</strong>。产品还没做，收的是「早鸟价 + 明确交付日期」。愿意预付的人才是真需求——口头说「我会买」的连参考价值都有限，掏钱的才是数据。注意兑现义务：预售金额小、交付承诺保守（宁可说两周交个简版，别许诺一个月交全套），收了钱就要交付，这是信用问题。</p><p><strong>形态三：人工服务替代（Wizard of Oz）</strong></p><p>最被低估的一招：<strong>用户以为在用产品，其实后面是你在手工干活</strong>。想做自动周报工具？先承诺「每周一自动发」，实际每周一你自己用 AI 花十分钟生成发过去。用户获得完整体验，你用劳动换取两样东西：真实使用数据 + 对「自动化到底有多难」的第一手认知。很多自动化产品最终放弃，就是因为人工跑了一遍才发现流程根本无法标准化——这一步在写代码前花两周就能知道。</p><p>三条形态的共同点：<strong>验证成本都以「天」计，而不是以「月」计</strong>。这正是它存在的理由。</p><h3 id="_2-最小验证指标-一个主指标-两个护栏" tabindex="-1">2. 最小验证指标：一个主指标 + 两个护栏 <a class="header-anchor" href="#_2-最小验证指标-一个主指标-两个护栏" aria-label="Permalink to “2. 最小验证指标：一个主指标 + 两个护栏”">​</a></h3><p>验证最忌讳「看一堆数据然后挑好看的解读」。提前把指标钉死，只认三类：</p><p><strong>主指标（只认一个，与验证形态对应）</strong>：</p><table tabindex="0"><thead><tr><th>验证形态</th><th>主指标</th><th>及格线参考</th></tr></thead><tbody><tr><td>落地页</td><td>留资转化率</td><td>访问者中约 5%+ 留下联系方式（示意值，按渠道质量调整）</td></tr><tr><td>预售</td><td>真实付费数</td><td>例如 72 小时内 ≥ 3 单（量级自己定，关键是提前写死）</td></tr><tr><td>人工服务</td><td>主动续费/加单率</td><td>服务过的人里，例如 1/3 愿意继续</td></tr></tbody></table><p><strong>两个护栏指标</strong>（防止单指标好看但整体变味）：</p><ol><li><strong>成本护栏</strong>：这个信号花了多少钱/多少小时？换算成「获得一个付费用户的成本」，高于你的可接受值，信号再好也是买来的假象；</li><li><strong>质量护栏</strong>：用户是谁？来的如果全是同行捧场、羊毛党、或者根本不是目标人群，转化率再高也作废。</li></ol><p><strong>指标必须提前写下来</strong>，连同截止日期：「到 11 月 15 日，若付费 &lt; 3 单，则……」。写在做事之前，是为了防止事后合理化——人对自己投入过的项目会不自觉地放水，这是所有验证失败的根源。</p><h3 id="_3-止损条件-什么情况下停" tabindex="-1">3. 止损条件：什么情况下停 <a class="header-anchor" href="#_3-止损条件-什么情况下停" aria-label="Permalink to “3. 止损条件：什么情况下停”">​</a></h3><p>止损有两种，都要提前定义：</p><p><strong>硬止损（到点就执行，不辩论）</strong>：</p><ul><li>时间到 + 主指标不达标 → 停止该方向，转入复盘；</li><li>连续 N 轮小步迭代，指标无任何移动 → 说明方向性错误，不是执行问题；</li><li>触及合规红线、与主业冲突不可调和 → 立即停，没有商量余地。</li></ul><p><strong>软止损（允许一次修正机会）</strong>：如果数据不好但<strong>用户反馈里出现了你原本没设计的用法</strong>，说明问题可能在切入点而非需求本身——可以按反馈调整一次（换人群/换卖点），重新走一轮验证，但只给一轮。</p><p><strong>止损时必须做的动作</strong>：不是默默关掉，而是走一遍「项目复盘模板与方法」那篇的复盘流程。止损的产出不是一个「失败」标记，而是一份可复用的资产（见复盘一文）。<strong>止损止得有记录，前面花的钱和时间才转化为经验而不是沉没成本。</strong></p><p>一个心态提示：验证失败率本来就高——这不是你不行，是验证机制在正常工作。用两周和几百块筛掉一个死项目，恰恰是这套流程最大的收益，它省下的是原本会投入的那两三个月。</p><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to “关键要点”">​</a></h2><ul><li>MVP 的「M」是验证的最小动作，不是产品的最小版本——先验证付费意愿，再碰代码；</li><li>三种低成本形态：落地页（留资）、预售（掏钱才算数）、人工服务替代（用手工换数据与认知）；</li><li>指标提前写死：一个主指标（对齐形态）+ 成本护栏 + 质量护栏，防止事后挑数据；</li><li>止损分硬止损（到点执行）与软止损（允许按反馈修正一次，且只给一次）；</li><li>止损必须伴随复盘记录——把沉没成本转成资产，这个项目才算没白做。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>低成本验证的完整逻辑是：<strong>用天和百元级别的成本，去回答「有没有人要」这个唯一重要的问题；用提前写死的指标和截止日期，防住自己对自己的放水；用止损即复盘的习惯，保证每一次失败都留下资产</strong>。对第一次做副业的工程师，这套流程最大的价值甚至不是找到能成的项目——而是让你用最小的代价，获得「这个方向不行」的确定性，然后信心十足地把它放下。</p>',31)])])}const _=a(o,[["render",s]]);export{c as __pageData,_ as default};
